def direct_imports():
    found = {}
    for line in source.read_text().splitlines():
        if line.startswith('import '):
            for name in line[7:].split():
                rel = name.replace('.', '/') + '.olean'
                selected = next((Path(root)/rel for root in env['LEAN_PATH'].split(':') if (Path(root)/rel).is_file()), None)
                need(selected is not None, 'missing direct import '+name)
                found[name] = {'path':str(selected), 'sha256':sha(selected), 'real_path':str(selected.resolve())}
    need(set(found)==set(expected_direct), 'direct import list changed')
    for name, want in expected_direct.items():
        need(found[name]['path']==want['path'] and found[name]['sha256']==want['sha256'], 'direct import mismatch '+name)
    return found
